import {readFileSync,writeFileSync} from 'node:fs';
import {createPublicClient,http,encodeFunctionData} from 'viem';
const c=createPublicClient({transport:http('https://base-rpc.publicnode.com')});
const state=JSON.parse(readFileSync('../adapter-current-catalog.json')),art=JSON.parse(readFileSync('../adapter-release-artifact.json'));
const catalogAbi=JSON.parse(readFileSync('contracts/EnclaveAppCatalog.abi.json')),ledgerAbi=JSON.parse(readFileSync('contracts/EnclaveDeployments.abi.json'));
const id='0x7ae476a3a1e4b0b144248075ff6656a0a10c3ae4cea8b6e4ad2b59dd8989ce33',ledger='0xb1783b61e1fdee6a6163dc3cdac27bf32e7d117b';
const d=await c.readContract({address:ledger,abi:ledgerAbi,functionName:'get',args:[id]});
const v=state.v[0],config=JSON.parse(v.config),options=JSON.parse(d.configCid);
config.upload.walletAudience=id;options.config=config;
const args=[state.a.slug,state.a.name,state.a.description,'1.0.16',art.cid,[v.vramMb,v.gpuGflops,v.memMb,v.cpuGflops],v.ports,v.config,0n];
const from=state.a.publisher;if(d.owner.toLowerCase()!==from.toLowerCase())throw Error('owner changed');
const result=await c.simulateContract({account:from,address:state.catalog,abi:catalogAbi,functionName:'publishVersion',args});
const index=Number(result.result[1]);if(index!==16)throw Error('catalog changed');
const ref=`catalog://${state.a.appId}/${index}`;
const publish={chainId:8453,from,to:state.catalog,value:'0x0',data:encodeFunctionData({abi:catalogAbi,functionName:'publishVersion',args})};
publish.estimatedGas=(await c.estimateGas({account:from,to:publish.to,data:publish.data})).toString();
const calls=[encodeFunctionData({abi:ledgerAbi,functionName:'setAppRef',args:[id,ref]}),encodeFunctionData({abi:ledgerAbi,functionName:'setConfig',args:[id,JSON.stringify(options)]})];
const upgrade={chainId:8453,from,to:ledger,value:'0x0',data:encodeFunctionData({abi:ledgerAbi,functionName:'multicall',args:[calls]})};
await c.simulateContract({account:from,address:ledger,abi:ledgerAbi,functionName:'multicall',args:[calls]});
upgrade.estimatedGas=(await c.estimateGas({account:from,to:ledger,data:upgrade.data})).toString();
const out={status:'prepared-not-signed',artifact:art,source:'https://github.com/EnclaveHost/enclave-apps/pull/3',deployment:id,oldAppRef:d.appRef,newAppRef:ref,version:'1.0.16',catalogConfig:JSON.parse(v.config),deploymentConfig:options,transactions:[{purpose:'Publish adapter version 1.0.16 with unchanged generic defaults; simulated successfully',...publish},{purpose:'After verifying the published approved version, atomically upgrade only this deployment and bind its upload audience to its own deployment ID; simulated successfully',...upgrade}],notes:['Legacy uploads remain available. Direct EOA uploads need no nan-issued token.','The deployment-specific audience is set only in this deployment override, not in the generic catalog template.','Contract wallets, sessions, Sia indexd, bootstrap and host control still require further migration.','wasm-tools component wit confirms WASI 0.2 imports; retain existing routing flags despite self-referential scanner string false positives.']};
writeFileSync('../../outputs/adapter-release/transactions.json',JSON.stringify(out,null,2)+'\n');
console.log(JSON.stringify({simulated:['publish','atomic version and config update'],gas:[publish.estimatedGas,upgrade.estimatedGas]}));
